-- Power Forms: questions filled in from the patient's chart (Kieran, Oct
-- 2026: "autofill the patient's saved info"). Updates the Initial Clearance
-- Forms added on 2026-10-29 so their name, date of birth, address, parent
-- and date questions fill in, only where nobody has edited the form in the
-- builder since. Safe to run more than once.
UPDATE "PowerFormTemplates" SET fields = $pf$[{"id":"att_health","type":"heading","label":"Health","help":"Please understand that it is your responsibility to consult a physician regarding your child's participation in all programs and treatments prior to attending. By signing this you believe that your child is in good health and in proper physical condition to participate in such activities. It is your responsibility to inform your child's therapist, of any injuries and/or limitations that might affect their ability to participate.","required":false},{"id":"att_sickness","type":"heading","label":"Sickness Policy","help":"Help and cooperation is required in order to maintain a healthy environment. Please notify your provider as soon as possible if your child appears sick. If your child has experienced a fever, vomiting and/or diarrhea, he/she should not return to therapy until 24 hours have passed since the last episode of the same.\n\nChildren will not be seen if any of the following are present:\n• Fever over 100.3\n• Continual runny nose\n• Too ill or uncomfortable to function in the therapy setting\n• Thick or discolored nasal discharge\n• Excessive sneezing or mucus-producing cough\n• Diarrhea or vomiting\n• Severe cough, mucus-producing cough or trouble breathing\n• Rash/ Infected skin patches\n• Conjunctivitis (pink eye)\n• Sore throat","required":false},{"id":"att_cancel","type":"heading","label":"Cancellations","help":"Please notify your provider 24 hours prior to a scheduled appointment if you need to cancel for any reason. Please note that excessive cancellations, LATE cancellations (day of/less than 24 hours) will result in your child switching to a flex schedule (see below).","required":false},{"id":"att_noshow","type":"heading","label":"No Shows","help":"We understand that emergencies happen but after 2 no shows within 1 month your child will be switched to a flex schedule. Please be considerate of your therapist's time and schedule.\n\nMake-ups will be given based upon availability and be given according to your child's therapy mandate. No makeups will be given for no shows.","required":false},{"id":"att_flex","type":"heading","label":"Flex Schedule","help":"The flex schedule allows more flexibility for families whose schedules change week to week. This can be due to medical appointments or other circumstances in which regular appointment days and times are challenging. When on the flex schedule, there is no guarantee of the availability of your provider's specific day or time.\n\nYour child will be switched to a 'Flex Schedule' for the following reasons\n- Excessive Cancellations\n- Attendance Requirement - Your child must attend at least 80% of their scheduled sessions in a 3-month period to keep their assigned day and time\n    Examples (within a 3 month period):\n    1x/week (12 sessions/3 months) → MUST attend at least 10 (allowed 2 cancellations)\n    2x/week (24 sessions/3 months) → MUST attend at least 20 (allowed 4 cancellations)\n    3x/week (36 sessions/3 months) → MUST attend at least 30 (allowed 6 cancellations)\n• Two No shows in a 1 month period may result in immediate Flex Schedule\n    ★ NOTE: After 2 months, attendance will be reviewed\n    → If below 80%, a warning will be issued\n    → At the end of 3 months: If attendance is still below 80%, your child may be moved to a Flex Schedule.\n\nWe try our best to work with you. If your assigned time/day no longer works, please let us know and we will try our best to accommodate. Consistent attendance is essential for your child's progress.","required":false},{"id":"att_additional","type":"heading","label":"Additional attendance policies","help":"★ Any changes to a client's physical status (recent extended hospitalizations, surgery etc) - a new prescription will be needed and/or a doctor's note to return (please check with the front desk).\n★ Scheduled absences of 3 weeks or greater due to travel etc - clients appointment day/time will not be held.","required":false},{"id":"att_sign","type":"heading","label":"Attendance Policies","help":"★ Please sign and return to The Kidz Lounge\n\nBy signing I certify that I have reviewed and agree to The Kidz Lounge Attendance Policies. I understand that excessive cancellations and/or no shows may result in termination of services or a switch to a flex schedule.","required":false},{"id":"att_immunizations","type":"yesno","label":"To the best of my knowledge I certify that my child's immunizations are up to date.","help":"(we are obligated to be aware of children who are not vaccinated in order to notify you of an outbreak)","required":true},{"id":"att_child_name","type":"text","label":"Child's Name","help":null,"required":true,"prefill":"child_name"},{"id":"att_child_dob","type":"date","label":"Date of Birth","help":null,"required":true,"prefill":"child_dob"},{"id":"att_signature","type":"signature","label":"Parents signature","help":null,"required":true},{"id":"att_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"att_footer","type":"heading","label":"Attendance Policy 10/22","help":"Updated April 2026","required":false}]$pf$::jsonb
WHERE name = $pf$Attendance Policies$pf$ AND created_by = 'system' AND updated_at IS NULL;
UPDATE "PowerFormTemplates" SET fields = $pf$[{"id":"doc_first","type":"text","label":"Name: First","help":null,"required":true,"prefill":"child_first"},{"id":"doc_last","type":"text","label":"Name: Last","help":null,"required":true,"prefill":"child_last"},{"id":"doc_dob","type":"date","label":"Birth Date","help":null,"required":true,"prefill":"child_dob"},{"id":"doc_permission","type":"heading","label":"Permission","help":"I give the Kidz Lounge permission to contact my child's doctor, listed below, to obtain necessary medical paperwork to facilitate the treatment process.","required":false},{"id":"doc_name","type":"text","label":"Doctor's Name","help":null,"required":true},{"id":"doc_phone","type":"phone","label":"Phone Number","help":null,"required":true},{"id":"doc_fax","type":"phone","label":"Fax Number","help":null,"required":false},{"id":"doc_parent","type":"text","label":"Parent's Name","help":null,"required":true,"prefill":"parent_name"},{"id":"doc_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"doc_signature","type":"signature","label":"Signature","help":null,"required":true}]$pf$::jsonb
WHERE name = $pf$Permission to Request Doctor Prescription for Services$pf$ AND created_by = 'system' AND updated_at IS NULL;
UPDATE "PowerFormTemplates" SET fields = $pf$[{"id":"eml_parent","type":"text","label":"Parent's Name","help":null,"required":true,"prefill":"parent_name","chart_field":"Parent_Name"},{"id":"eml_email","type":"email","label":"E-mail Address","help":null,"required":true,"prefill":"parent_email","chart_field":"Parent_Email"},{"id":"eml_cell","type":"phone","label":"Cell Phone","help":null,"required":true,"prefill":"parent_phone","chart_field":"Parent_Phone"},{"id":"eml_child","type":"text","label":"Child's Name","help":null,"required":true,"prefill":"child_name"},{"id":"eml_dob","type":"date","label":"D.O.B.","help":null,"required":true,"prefill":"child_dob"},{"id":"eml_risks","type":"heading","label":"Risks of using e-mail and text","help":"At your request, you have chosen to communicate personally identifiable information concerning your child's early intervention treatment by e-mail and/or text without the use of encryption. Sending personally identifiable information by e-mail has a number of risks that you should be aware of prior to giving your permission. These risks include, but are not limited to, the following:\n\n• E-mail and text can be forwarded and stored in electronic and paper format easily without prior knowledge of the parent.\n• E-mail or text senders can misaddress an e-mail or text and personally identifiable information can be sent to incorrect recipients by mistake.\n• E-mail sent over the Internet without encryption is not secure and can be intercepted by unknown third parties.\n• E-mail and text content can be changed without the knowledge of the sender or receiver.\n• Backup copies of e-mail and text messages may still exist even after the sender and receiver have deleted the messages.\n• Employers and online service providers have a right to check e-mail sent through their systems.\n• E-mail can contain harmful viruses and other programs.","required":false},{"id":"eml_ack","type":"heading","label":"Parental Acknowledgement and Agreement","help":"I acknowledge that I have read and understand the items above which describe the inherent risks of using e-mail and text messages to communicate personally identifiable information. Nevertheless, I authorize the below listed to communicate with me at my e-mail address and cell phone number listed above, concerning my child's participation in the Early Intervention Program (EIP), including but not limited to communication regarding service delivery, his/her progress in the EIP and any other related matters. I understand that use of e-mail without encryption presents the risks noted above and may result in an unintended disclosure of such information.","required":false},{"id":"eml_team_ok","type":"yesno","label":"I give permission for members of my child's treatment team to communicate personally identifiable information concerning my child with each other using unencrypted e-mail or texting.","help":"Early intervention team members who I give permission to use unencrypted e-mail or to text to communicate with each other about my child include:","required":true},{"id":"eml_team1_name","type":"text","label":"(1) Name","help":null,"required":false},{"id":"eml_team1_email","type":"email","label":"(1) at the e-mail address","help":null,"required":false},{"id":"eml_team1_phone","type":"phone","label":"(1) Phone to text","help":null,"required":false},{"id":"eml_team2_name","type":"text","label":"(2) Name","help":null,"required":false},{"id":"eml_team2_email","type":"email","label":"(2) at the e-mail address","help":null,"required":false},{"id":"eml_team2_phone","type":"phone","label":"(2) Phone to text","help":null,"required":false},{"id":"eml_team3_name","type":"text","label":"(3) Name","help":null,"required":false},{"id":"eml_team3_email","type":"email","label":"(3) at the e-mail address","help":null,"required":false},{"id":"eml_team3_phone","type":"phone","label":"(3) Phone to text","help":null,"required":false},{"id":"eml_signature","type":"signature","label":"Parent's Signature","help":null,"required":true},{"id":"eml_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"eml_photo","type":"yesno","label":"I give permission to use photographs/ videos of my child for promotional purposes.","help":null,"required":true,"chart_field":"Picture_Consent"},{"id":"eml_footer","type":"heading","label":"Email/txt/ photo consent 10/21","help":null,"required":false}]$pf$::jsonb
WHERE name = $pf$Parental Consent to Use E-mail and/or Texting to Exchange Personally Identifiable Information & Photo release$pf$ AND created_by = 'system' AND updated_at IS NULL;
UPDATE "PowerFormTemplates" SET fields = $pf$[{"id":"rec_ack","type":"heading","label":"Acknowledgement","help":"I have read and understand my rights as a parent/legal guardian to have access to my child's records as described by The Kidz Lounge in the letter entitled “Parental Access Children's Records”.","required":false},{"id":"rec_child","type":"text","label":"Childs Name","help":null,"required":true,"prefill":"child_name"},{"id":"rec_dob","type":"date","label":"Date of Birth","help":null,"required":true,"prefill":"child_dob"},{"id":"rec_signature","type":"signature","label":"Signed","help":null,"required":true},{"id":"rec_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"rec_relationship","type":"text","label":"Relationship to child","help":null,"required":true,"prefill":"relationship","chart_field":"Relationship_To_Patient"},{"id":"rec_footer","type":"heading","label":"** Send back to The Kidz Lounge","help":null,"required":false}]$pf$::jsonb
WHERE name = $pf$Parental Access To Child's Records$pf$ AND created_by = 'system' AND updated_at IS NULL;
UPDATE "PowerFormTemplates" SET fields = $pf$[{"id":"rel_child","type":"text","label":"Child's Name","help":null,"required":true,"prefill":"child_name"},{"id":"rel_ei","type":"text","label":"EI #","help":null,"required":true,"prefill":"ei_number"},{"id":"rel_dob","type":"date","label":"DOB","help":null,"required":true,"prefill":"child_dob"},{"id":"rel_address","type":"text","label":"Address","help":null,"required":true,"prefill":"address"},{"id":"rel_apt","type":"text","label":"Apt #","help":null,"required":false,"prefill":"address_line2"},{"id":"rel_city","type":"text","label":"City/Town","help":null,"required":true,"prefill":"city"},{"id":"rel_state","type":"text","label":"State","help":null,"required":true,"default":"New York","prefill":"state"},{"id":"rel_zip","type":"text","label":"Zip Code","help":null,"required":true,"prefill":"zip"},{"id":"rel_parent","type":"text","label":"I, (Parent/Guardian's Full Name)","help":"seek services for my child from the NYC Early Intervention Program. I understand that the providers (including evaluators, service providers and service coordinators) offering Early Intervention (EI) services to my child and family may need to exchange information to develop and carry out the Individualized Family Service Plan (IFSP).","required":true,"prefill":"parent_name"},{"id":"rel_direction","type":"choice","label":"(Check one)","help":null,"required":true,"options":["I authorize for the information below to be released","I authorize for the information below to be obtained"],"default":"I authorize for the information below to be released"},{"id":"rel_info","type":"checkboxes","label":"Specific information to be released/obtained:","help":null,"required":true,"options":["EI Medical Form","Multidisciplinary Evaluation","Supplemental Evaluation(s)","Individualized Family Service Plan","Provider Progress Notes","Session Notes","Other"],"default":["EI Medical Form","Multidisciplinary Evaluation","Supplemental Evaluation(s)","Individualized Family Service Plan","Provider Progress Notes","Session Notes"]},{"id":"rel_supplemental","type":"text","label":"Supplemental Evaluation(s) Specify:","help":null,"required":false},{"id":"rel_info_other","type":"text","label":"Other:","help":null,"required":false},{"id":"rel_abc","type":"checkboxes","label":"I authorize for the information to be (check/complete either A, B, or C):","help":null,"required":true,"options":["A. Released to all EI providers providing evaluation, service coordination, or services to my child and family","B. Released to the Individual/Agency below","C. Obtained from the Individual/Agency below"],"default":["A. Released to all EI providers providing evaluation, service coordination, or services to my child and family","B. Released to the Individual/Agency below"]},{"id":"rel_b_h","type":"heading","label":"B. Released to the Individual/Agency below:","help":null,"required":false},{"id":"rel_b_name","type":"text","label":"(Name/ Organization)","help":null,"required":false,"default":"The Kidz Lounge Related Services"},{"id":"rel_b_address","type":"text","label":"(Street Address, Borough/City, Zip Code)","help":null,"required":false,"default":"8212 151st Ave. Howard Beach, NY 11414"},{"id":"rel_b_phone","type":"phone","label":"(Telephone Number)","help":null,"required":false,"default":"(718) 848-0875"},{"id":"rel_b_fax","type":"phone","label":"(Fax Number)","help":null,"required":false},{"id":"rel_c_h","type":"heading","label":"C. Obtained from the Individual/Agency below:","help":null,"required":false},{"id":"rel_c_name","type":"text","label":"(Name/ Organization)","help":null,"required":false},{"id":"rel_c_address","type":"text","label":"(Street Address, Borough/City, Zip Code)","help":null,"required":false},{"id":"rel_c_phone","type":"phone","label":"(Telephone Number)","help":null,"required":false},{"id":"rel_c_fax","type":"phone","label":"(Fax Number)","help":null,"required":false},{"id":"rel_to_h","type":"heading","label":"The information will be sent to:","help":null,"required":false},{"id":"rel_to_name","type":"text","label":"(Name/ Organization)","help":null,"required":false},{"id":"rel_to_address","type":"text","label":"(Street Address, Borough/City, Zip Code)","help":null,"required":false},{"id":"rel_to_phone","type":"phone","label":"(Telephone Number)","help":null,"required":false},{"id":"rel_to_fax","type":"phone","label":"(Fax Number)","help":null,"required":false},{"id":"rel_purpose","type":"checkboxes","label":"D. The purpose of the requested information is to: (check all that apply)","help":null,"required":false,"options":["Establish Early Intervention eligibility","Develop an Individualized Family Service Plan","Start, coordinate and monitor Early Intervention services","Inform the child's physician about my child's services and","Other"]},{"id":"rel_purpose_other","type":"text","label":"Other:","help":null,"required":false},{"id":"rel_ends","type":"date","label":"This release ends on the date of my next scheduled IFSP (or, if sooner, specify date)","help":"I understand that this release can be withdrawn at any time upon written notice to my Service Coordinator.","required":false},{"id":"rel_signature","type":"signature","label":"Signed","help":null,"required":true},{"id":"rel_relationship","type":"text","label":"Relationship to Child","help":null,"required":true,"prefill":"relationship","chart_field":"Relationship_To_Patient"},{"id":"rel_date","type":"date","label":"Date","help":null,"required":true,"prefill":"today"},{"id":"rel_note","type":"heading","label":"NOTE","help":"A reproduced copy of this signed form is deemed to have the same force and effect as the original. A new Consent to Release Information form must be signed at the initial IFSP meeting and at each IFSP review and annual meeting. Blank consent forms should never be signed by the parent.\n\nConsent to Release/Obtain Information Revised 12/10","required":false}]$pf$::jsonb
WHERE name = $pf$NYC Early Intervention Program Consent to Release/Obtain Information$pf$ AND created_by = 'system' AND updated_at IS NULL;

-- Cancelled forms are no longer kept (Kieran, Oct 2026): remove the ones
-- cancelled before, and any package link left with no forms.
DELETE FROM "PowerFormRequests" WHERE status = 'cancelled';
DELETE FROM "PowerFormPackets" k WHERE NOT EXISTS (SELECT 1 FROM "PowerFormRequests" r WHERE r.packet_id = k.id);
